// `Output = "N"` and `OutputIndex = k`: a selection over the call. Two equal calls share a group.
/// @asset Path(Game, "Functions/MF_LpSplit")
extern void MF_LpSplit(float2 UV, out float3 Head, out float Tail);

/// @name M_LpSelectors
export void M_LpSelectors(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float Alpha = 0;
    float2 uv = UE.TexCoord(Index = 0);
    Color = MF_LpSplit(uv).Head;
    Alpha = MF_LpSplit(uv)[1];
    Base.EmissiveColor = Color;
    Base.Opacity = Alpha;
}
